from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up all devices.
prime_hub = PrimeHub()
left = Motor(Port.B, Direction.CLOCKWISE)
right = Motor(Port.A, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(left, right, 56, 114)
motor = Motor(Port.C, Direction.COUNTERCLOCKWISE)


# The main program starts here.
drive_base.settings(straight_acceleration=300)
drive_base.settings(straight_speed=500)
wait(3000)
drive_base.straight(650)
print(drive_base.angle())
wait(3000)
drive_base.turn(-20)
wait(3000)
motor.run_angle(255, -60)
wait(3000)
drive_base.straight(15)
wait(3000)
motor.run_angle(255, -40)
# Go Back!
wait(3000)
drive_base.straight(-50)
wait(3000)
drive_base.turn(30)
wait(3000)
drive_base.straight(-670)
